import {landmarks,geoStops,project,regions,worldId} from './coastal-geography.js';
import {stationArt,stationArtUrl} from './coastal-station-art.js';
import {cityQuestions,cityWikipedia} from './coastal-city-learning.js';
const kinds=['clock','dome','bridge','library','townhall','castle','museum','pier','castle','university','castle','university','clock','church','ship','bridge','cathedral','arch','bridge','bridge','castle','tower','tunnel','pier','cathedral','square','atoms','station','castle','houses','bridge','palace','gate','cathedral','concert'];
const natural=new Set(['mountain','lake','stones','cliffs']);
const facts={Stonehenge:'A prehistoric stone circle in Wiltshire: a human-made landmark.', 'White Cliffs of Dover':'Chalk cliffs on the English Channel, facing towards France.', 'Lake District':'A landscape of lakes and mountains in north-west England.', 'Eryri / Snowdonia':'A national park in north Wales known for its mountain landscapes.', 'Loch Ness':'A long freshwater lake in the Scottish Highlands. Loch is a Scottish word for a lake.', 'Ben Nevis':'The highest mountain in the United Kingdom.', "Giant's Causeway":'Basalt columns formed through volcanic activity on the coast of Northern Ireland.', 'Cliffs of Moher':'High sea cliffs on the Atlantic coast of the Republic of Ireland.', 'Mont-Saint-Michel':'An abbey and settlement on a tidal island in Normandy.', 'Dutch windmills':'The windmills at Kinderdijk help manage water and drain low-lying land.'};
const wiki={'Eryri / Snowdonia':'Snowdonia',"Giant's Causeway":'Giant%27s_Causeway','Dutch windmills':'Kinderdijk','Lake District':'Lake_District'};
export const mapLandmarks=[...landmarks.map(([name,lon,lat,region,kind],i)=>{const art=stationArt.find(a=>a.landmark.includes(name));return {id:'place-'+i,name,...project(lon,lat),region,kind:name==="Giant's Causeway"?'basalt':name==='Mont-Saint-Michel'?'cathedral':kind,city:art?.id,natural:natural.has(kind)&&name!=='Stonehenge',description:facts[name]??(art?cityQuestions(art.id)[2].explanation:'Explore this landmark in your country atlas.'),source:art?cityWikipedia(art.id):'https://en.wikipedia.org/wiki/'+(wiki[name]??encodeURIComponent(name.replaceAll(' ','_')))};}),...stationArt.filter(a=>!landmarks.some(([name])=>a.landmark.includes(name))).map(a=>({id:'city-'+a.id,name:a.landmark,x:geoStops[a.id].x,y:geoStops[a.id].y,region:geoStops[a.id].region,city:a.id,kind:kinds[a.id],natural:false,description:cityQuestions(a.id)[2].explanation,source:cityWikipedia(a.id)}))];
export const landmarkImage=place=>place.image??(Number.isInteger(place.city)?stationArtUrl(place.city):new URL('../assets/coastal/landmarks/'+place.id+'.jpg',import.meta.url).href);
export function visibleLandmarks(state){const visible=new Set(regions.filter(r=>r.round<=state.round).map(r=>r.id));return mapLandmarks.filter(l=>visible.has(l.region)&&(!Number.isInteger(l.city)||geoStops[l.city].round<=state.round));}
// Resolve offsets once in world coordinates. Camera movement only translates them;
// screen edges and newly unlocked places never rearrange existing landmarks.
let anchoredLandmarks;export function resetLandmarkAnchors(){anchoredLandmarks=null;}
function getAnchors(){if(anchoredLandmarks)return anchoredLandmarks;anchoredLandmarks=(()=>{const occupied=geoStops.map(s=>({x:s.x,y:s.y,w:68,h:64})),positions=new Map();
 for(const place of [...mapLandmarks].sort((a,b)=>Number.isInteger(b.city)-Number.isInteger(a.city))){let pos;
  for(const distance of [1,1.5,2,2.5,3,4,5]){for(const [dx,dy]of [[55,-66],[-65,-66],[70,62],[-70,62],[0,-112],[112,-12],[-112,-12],[0,104]]){const p={x:place.x+dx*distance,y:place.y+dy*distance,w:60,h:48};if(!occupied.some(o=>Math.abs(p.x-o.x)<(p.w+o.w)/2&&Math.abs(p.y-o.y)<(p.h+o.h)/2)&&geoStops.every(s=>Math.hypot(p.x-s.x,p.y-s.y)>58)){pos=p;break;}}if(pos)break;}
  pos??={x:place.x+55,y:place.y-66,w:60,h:48};occupied.push(pos);positions.set(place.id,pos);
 }return positions;})();return anchoredLandmarks;}
export function landmarkLayout(state){const {zoom,x,y}=state.camera,kg=worldId==='kyrgyzstan';return visibleLandmarks(state).flatMap(place=>{const pos=getAnchors().get(place.id),sx=pos.x*zoom+x,sy=pos.y*zoom+y;if(sx< -150||sx>1150||sy< -150||sy>750)return [];return [{...place,drawX:pos.x,drawY:pos.y,size:kg?(zoom<1.2?12:zoom<1.8?21:30):zoom<.7?25:34,label:kg?zoom>=1.7:zoom>=.7}];});}
export function landmarkAt(state,p){return landmarkLayout(state).find(l=>Math.hypot(p.x-l.drawX,p.y-l.drawY)*state.camera.zoom<l.size*.75)??null;}
